    <script>
      (function() {
        function persistStoreHandle() {
          const params = new URLSearchParams(window.location.search);
          let handle = params.get('sh');

          if (!handle) {
            const pathParts = window.location.pathname.split('/');
            const colIndex = pathParts.indexOf('collections');
            if (colIndex !== -1 && pathParts[colIndex + 1]) {
              handle = pathParts[colIndex + 1];
            }
          }

          if (handle) {
            const links = document.querySelectorAll('a[href*="/products/"]');
            links.forEach(link => {
              const url = new URL(link.href, window.location.origin);
              if (!url.searchParams.has('sh')) {
                url.searchParams.set('sh', handle);
                link.href = url.toString();
              }
            });
          }
        }

        persistStoreHandle();
        const observer = new MutationObserver(persistStoreHandle);
        observer.observe(document.body, { childList: true, subtree: true });
      })();
    </script>

    {%- comment -%}
      STELLA & SAGE STOREFRONT FORM AUTH BRIDGE
      This mirrors the dashboard login behavior, but for the storefront form.
      It intercepts logged-out form submit before the form's inline handler can send the customer anywhere else.
    {%- endcomment -%}
    <script>
      (function () {
        var isLoggedIn = {% if customer %}true{% else %}false{% endif %};
        var loginBase = {{ routes.account_login_url | json }};
        var fallbackForm = '/pages/private-storefronts';

        function getPending() {
          try {
            var raw = localStorage.getItem('sf_pending_form_v2') || localStorage.getItem('sf_pending_form_v1');
            return raw ? JSON.parse(raw) : null;
          } catch (e) {
            return null;
          }
        }

        function savePendingReturnPath() {
          try {
            var raw = localStorage.getItem('sf_pending_form_v2') || localStorage.getItem('sf_pending_form_v1');
            var data = raw ? JSON.parse(raw) : {};
            data.return_path = window.location.pathname || fallbackForm;
            data._saved_at = Date.now();
            localStorage.setItem('sf_pending_form_v2', JSON.stringify(data));
            localStorage.removeItem('sf_pending_form_v1');
          } catch (e) {}
        }

        if (!isLoggedIn) {
          document.addEventListener('submit', function (event) {
            var form = event.target;
            if (!form || form.id !== 'sf-request-form') return;
            // The anonymous trial form owns its own private build flow. Let its
            // submit handler save the request and open the public waiting room.
            // Legacy signed-out request forms without this explicit marker
            // still use the account-first bridge below.
            if (form.dataset && form.dataset.signedIn === 'false') return;

            if (typeof window.generateHandle === 'function') window.generateHandle();
            if (typeof window.validateBeforeSubmit === 'function' && !window.validateBeforeSubmit()) {
              event.preventDefault();
              event.stopImmediatePropagation();
              return false;
            }

            if (typeof window.sfSaveToSession === 'function') window.sfSaveToSession();
            savePendingReturnPath();

            event.preventDefault();
            event.stopImmediatePropagation();
            window.location.href = loginBase + '?return_url=' + encodeURIComponent(window.location.pathname || fallbackForm);
            return false;
          }, true);
        } else {
          var path = window.location.pathname || '';
          var onForm = (path === fallbackForm || path === '/pages/storefront');
          var pending = getPending();
          if (pending && !onForm) {
            var savedAt = Number(pending._saved_at || 0);
            var isFresh = !savedAt || ((Date.now() - savedAt) < (1000 * 60 * 60 * 12));
            if (isFresh) {
              window.location.replace(pending.return_path || fallbackForm);
            }
          }
        }
      })();
    </script>

